\copy (WITH claim_map AS (SELECT bib_key, string_agg(allowed_claim, ' | ' ORDER BY claim_map_id) AS allowed_claims, string_agg(forbidden_claim, ' | ' ORDER BY claim_map_id) AS forbidden_claims, string_agg(qsb_connection, ' | ' ORDER BY claim_map_id) AS qsb_connections FROM qsb_literature.reference_claim_map GROUP BY bib_key) SELECT rs.bib_key AS record_id, 'reference_source' AS source_table, 'qsb_literature' AS source_schema, rs.title, rs.authors, rs.year, COALESCE(NULLIF(rs.journal,''), NULLIF(rs.booktitle,''), '') AS venue, COALESCE(rs.doi,'') AS doi, COALESCE(rs.arxiv_id,'') AS arxiv_id, COALESCE(rs.url,'') AS url, rs.bib_key AS bibtex_key, COALESCE(rs.keywords,'') AS topic_tags, LEFT(COALESCE(rs.note,''), 240) AS abstract_or_note_excerpt, rs.run_id AS lineage_or_run_id, rs.source_file AS source_artifact_path, 'claim_status=' || rs.claim_status || '; physical_claim_release=' || rs.physical_claim_release || '; allowed_claims=' || COALESCE(cm.allowed_claims,'') || '; forbidden_claims=' || COALESCE(cm.forbidden_claims,'') AS claim_boundary FROM qsb_literature.reference_source rs LEFT JOIN claim_map cm ON cm.bib_key=rs.bib_key ORDER BY rs.bib_key) TO 'runs/QSB-PBR-LITERATURE-DWH-SCOUT-FOR-MECHANISTIC-BRAINSTORMING-01/data/dwh_literature_inventory.csv' WITH CSV HEADER

\copy (WITH records AS (SELECT bib_key, title, COALESCE(keywords,'') AS keywords, COALESCE(note,'') AS note, COALESCE(pillar_id,'') AS pillar_id FROM qsb_literature.reference_source), classified AS (SELECT bib_key AS record_id, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'planck|minimal-length|fundamental length|quantum-gravity|short-distance' THEN 'strong' ELSE 'none' END AS axis_planck_scale, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'qft-curved|curved-spacetime|curved space|hawking|unruh|hadamard|local-covariance' THEN 'strong' ELSE 'none' END AS axis_qft_curved_spacetime, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'emergent|entanglement|causal-set|thermodynamics|spin-networks|quantum-geometry|dynamic-geometry|coarse-graining|holography|tensor-networks' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'qft-curved|strings|curved-spacetime' THEN 'weak' ELSE 'none' END AS axis_emergence, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'loop-quantum-gravity|spin-networks|rovelli|ashtekar' THEN 'strong' ELSE 'none' END AS axis_loop_quantum_gravity, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'asymptotic-safety|reuter|coarse-graining' THEN 'strong' ELSE 'none' END AS axis_asymptotic_safety, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'string|worldsheet|sanchez|devega|internal-modes|multistring' THEN 'strong' ELSE 'none' END AS axis_string_theory, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'holography|ads/cft|entanglement-renormalization|tensor-networks' THEN 'strong' ELSE 'none' END AS axis_holography, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'operator|matrix|large-n|tensor-networks|spin-networks' THEN 'medium' ELSE 'none' END AS axis_matrix_operator, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'minimal-length|fundamental length|localization|finite-resolution|planck-boundary' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'planck|short-distance' THEN 'medium' ELSE 'none' END AS axis_uncertainty_scale_coupling, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'area|geometry|spin-networks|quantum-geometry|holography|entanglement-entropy|worldsheet' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'dynamic-geometry|curved-spacetime' THEN 'medium' ELSE 'none' END AS axis_area_geometry, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'modes|spectral|resonator|eigen|oscillation|internal-modes|stable-unstable' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'qft-curved|strings' THEN 'medium' ELSE 'none' END AS axis_resonator_spectral, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'causal-set|thermodynamics|black-hole|horizon|vacuum|particle' THEN 'medium' ELSE 'none' END AS axis_other, CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'minimal-length|fundamental length|planck-boundary|quantum-gravity-overview' THEN 'core_background' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'spin-networks|quantum-geometry|dynamic-geometry|operator|matrix|tensor-networks' THEN 'operator_geometry_context' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'emergent|holography|entanglement|causal-set|thermodynamics' THEN 'emergence_context' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'qft-curved|curved-spacetime|string|sanchez|devega' THEN 'pluralistic_context' ELSE 'unknown_requires_human_review' END AS mechanism_brainstorming_use, 'Literature context only; not internal QSB/PBR evidence; no candidate upgrade; physical_claim_release=blocked_no_physics_claim.' AS claim_safety_note FROM records) SELECT * FROM classified ORDER BY record_id) TO 'runs/QSB-PBR-LITERATURE-DWH-SCOUT-FOR-MECHANISTIC-BRAINSTORMING-01/data/dwh_literature_mechanism_axes.csv' WITH CSV HEADER

\copy (WITH records AS (SELECT bib_key, title, COALESCE(keywords,'') AS keywords, COALESCE(pillar_id,'') AS pillar_id FROM qsb_literature.reference_source), bubbles AS (SELECT bib_key AS record_id, title, bubble_name, relevance_level, claim_safety_note FROM records CROSS JOIN LATERAL (VALUES ('Raumzeit-Unschärfe / Skalenkopplung', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'minimal-length|fundamental length|localization|finite-resolution|planck-boundary' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'planck|short-distance' THEN 'medium' ELSE 'none' END), ('Schild Action / Flächenquantum / Worldsheet', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'string|worldsheet|area|geometry|curved-spacetime' THEN 'medium' ELSE 'none' END), ('Matrix / Large-N / Operatorstruktur', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'operator|matrix|large-n|tensor-networks|spin-networks' THEN 'medium' ELSE 'none' END), ('Nambu Brackets / Higher Gauge / Mehrfachrelationen', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'higher gauge|nambu|multiple relation' THEN 'weak' ELSE 'none' END), ('Dualität / Holographie / Reparametrisierungs-Invarianz', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'holography|ads/cft|entanglement-renormalization|duality' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'string|worldsheet' THEN 'medium' ELSE 'none' END), ('Nicht-Kommutativität / Reihenfolge der Operationen', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'non-commut|order|causal-set|partial-order' THEN 'medium' ELSE 'none' END), ('Spektrum / Resonator / Eigenstruktur', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'modes|spectral|resonator|eigen|oscillation|internal-modes|stable-unstable' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'qft-curved|strings' THEN 'medium' ELSE 'none' END), ('Loop Quantum Geometry / Geometriequanten', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'loop-quantum-gravity|spin-networks|quantum-geometry|rovelli|ashtekar' THEN 'strong' ELSE 'none' END), ('Asymptotic Safety / Scale Flow', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'asymptotic-safety|reuter|coarse-graining|scale' THEN 'strong' ELSE 'none' END), ('QFT in Curved Spacetime / Semiclassical Boundary', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'qft-curved|curved-spacetime|curved space|hawking|unruh|hadamard|local-covariance' THEN 'strong' ELSE 'none' END), ('Emergence Programs / Spacetime-from-Collective-Variables', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'emergent|entanglement|causal-set|thermodynamics|tensor-networks|holography' THEN 'strong' WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'dynamic-geometry|coarse-graining' THEN 'medium' ELSE 'none' END), ('Black-Hole / Horizon Thermodynamics', CASE WHEN lower(keywords || ' ' || title || ' ' || pillar_id) ~ 'black-hole|horizon|hawking|thermodynamics|entropy' THEN 'strong' ELSE 'none' END)) AS v(bubble_name,relevance_level) CROSS JOIN LATERAL (SELECT 'Brainstorming context only; no physical QSB/PBR claim released.' AS claim_safety_note) s) SELECT record_id, title, bubble_name, relevance_level, claim_safety_note FROM bubbles WHERE relevance_level <> 'none' ORDER BY bubble_name, record_id) TO 'runs/QSB-PBR-LITERATURE-DWH-SCOUT-FOR-MECHANISTIC-BRAINSTORMING-01/data/dwh_literature_to_brainstorming_bubbles_crosswalk.csv' WITH CSV HEADER

\copy (SELECT rs.bib_key AS record_id, rs.title, rs.claim_status, rs.physical_claim_release, cm.allowed_claim, cm.forbidden_claim, cm.review_status, 'Literature is external/motivational context only and is not internal evidence for QSB/PBR.' AS scout_boundary FROM qsb_literature.reference_source rs LEFT JOIN qsb_literature.reference_claim_map cm ON cm.bib_key=rs.bib_key ORDER BY rs.bib_key) TO 'runs/QSB-PBR-LITERATURE-DWH-SCOUT-FOR-MECHANISTIC-BRAINSTORMING-01/data/dwh_literature_claim_boundaries.csv' WITH CSV HEADER
